-- =============================================================================
-- 008 — Project ID (project_code) is generated by the database
--
-- Before: personnel typed the Project ID. UNIQUE(project_code) blocked exact
-- duplicates, but "26om0123" and "26OM0123" were both accepted and the ID could
-- be changed when the project was edited.
--
-- Now:
--   * Format stays as before: YY + OM + 4-digit sequence, e.g. 26OM0332.
--     YY = year of registration (Asia/Manila). The sequence restarts each year
--     and continues after the highest existing code of that year.
--   * A BEFORE INSERT trigger assigns the code. The counter row is updated with
--     INSERT ... ON CONFLICT DO UPDATE, which locks that year's row, so two
--     projects saved at the same moment always get different numbers.
--   * Application inserts (API = service_role) can never choose a code.
--     Only SQL run by the database owner (seed scripts) may insert a fixed code,
--     and it must still match the format.
--   * Codes are uppercase, unique regardless of letter case, and cannot be
--     changed after creation.
-- Existing 17 codes are unchanged (all already match the format).
-- =============================================================================

-- 1. Counter per year ---------------------------------------------------------
create table if not exists private.project_code_counters (
  year_2digit smallint primary key check (year_2digit between 0 and 99),
  last_seq    integer  not null check (last_seq >= 0),
  updated_at  timestamptz not null default now()
);
comment on table private.project_code_counters is 'Last Project ID sequence used per registration year (YY). Updated only by private.next_project_code().';

-- Start each year after the highest code already in use (e.g. 26OM0331 -> next 26OM0332).
insert into private.project_code_counters (year_2digit, last_seq)
select substr(project_code, 1, 2)::smallint, max(substr(project_code, 5)::integer)
from public.projects
where project_code ~ '^[0-9]{2}OM[0-9]{4,}$'
group by 1
on conflict (year_2digit) do update set last_seq = greatest(private.project_code_counters.last_seq, excluded.last_seq);

-- 2. Next code (atomic) --------------------------------------------------------
create or replace function private.next_project_code()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  yy   smallint := (extract(year from (now() at time zone 'Asia/Manila'))::integer % 100)::smallint;
  seq  integer;
  code text;
begin
  loop
    -- The ON CONFLICT update locks this year's counter row until the transaction ends,
    -- so concurrent registrations are serialised and never receive the same number.
    insert into private.project_code_counters as c (year_2digit, last_seq)
    values (yy, 1)
    on conflict (year_2digit) do update set last_seq = c.last_seq + 1, updated_at = now()
    returning c.last_seq into seq;

    code := lpad(yy::text, 2, '0') || 'OM' || case when seq < 10000 then lpad(seq::text, 4, '0') else seq::text end;
    -- Safety net: skip a number that was inserted by hand (seed SQL) without moving the counter.
    exit when not exists (select 1 from public.projects where upper(project_code) = code);
  end loop;
  return code;
end;
$$;
revoke all on function private.next_project_code() from public, anon, authenticated;
grant execute on function private.next_project_code() to service_role;
grant usage on schema private to service_role;

-- 3. Assign on insert ----------------------------------------------------------
-- SECURITY INVOKER on purpose: current_user is the caller's role.
create or replace function public.projects_assign_code()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.project_code is null
     or btrim(new.project_code) = ''
     or current_user in ('service_role', 'authenticated', 'anon') then
    new.project_code := private.next_project_code();
  else
    new.project_code := upper(btrim(new.project_code));
  end if;
  return new;
end;
$$;

drop trigger if exists projects_assign_code on public.projects;
create trigger projects_assign_code
  before insert on public.projects
  for each row execute function public.projects_assign_code();

-- 4. Never changes after creation --------------------------------------------
create or replace function public.projects_lock_code()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.project_code is distinct from old.project_code then
    raise exception 'The Project ID cannot be changed after the project is registered.'
      using errcode = 'P0001', hint = 'project_code is immutable';
  end if;
  return new;
end;
$$;

drop trigger if exists projects_lock_code on public.projects;
create trigger projects_lock_code
  before update of project_code on public.projects
  for each row execute function public.projects_lock_code();

-- 5. Format + case-insensitive uniqueness ------------------------------------
alter table public.projects
  drop constraint if exists projects_project_code_format,
  add constraint projects_project_code_format check (project_code ~ '^[0-9]{2}OM[0-9]{4,}$');

create unique index if not exists projects_project_code_upper_key on public.projects (upper(project_code));
-- The original UNIQUE (project_code) constraint is kept as well.
